INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_d84d780df1bda340c80526bb","wiki/sources/ril-423-1101-inb-2026-data.md",3,"Seite 2","Begriff (1) EinsatzmerkblÃ¤tter fÃ¼r Eisenbahnfahrzeuge enthalten\n\nfahrzeugseitige Angaben, die die MaÃŸnahmen der nichtpolizeilichen Gefahrenabwehr unterstÃ¼tzen.\n\nEinsatzmerkblÃ¤tter ersetzen nicht die fachliche fahrzeugtechnische Beratung und UnterstÃ¼tzung des ZB oder des\n\neinbezogenen EVU.\n\nGÃ¼ltig ab 09.12.2018",33,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174952/820b1600c2014069ba4816617d055714/Ril-423-1101-INB-2026-data.pdf\",\"normalized_sha256\":\"b9a4f2f733d0a347e43d4907cf8150abfba7a219ee8ffae53c7ca55d8379e4f9\",\"page\":2,\"source_id\":\"src_7982cd2d61d9b88505ea\",\"source_sha256\":\"8f686c9028cf9c6997fe357847bf62f5600781696595c2a4f187ab50c483a4c2\",\"source_version_id\":\"sv_f5f30bdad0d878ae4bfa9844\"}","9c1a7ea3d4e7b4d31d7ccd267eb2a228828316992521e96f68ddfe09adedad30"],["chunk_1eab82562d665b545f406ad0","wiki/sources/ril-423-1101-inb-2026-data.md",4,"Seite 3","Bahnbetrieb Notfallmanagement, Brandschutz\n\nGrundsÃ¤tze 423.1101\n\nSeite 3\n\n(2) FÃ¼r ein schnelles und effizientes Eindringen in Eisenbahn- Vorhaltung Einfahrzeuge sind EinsatzmerkblÃ¤tter gemÃ¤ÃŸ Muster der satzmerkblatt\n\nKonzernstelle Notfallmanagement vorzuhalten. Das Mus- fÃ¼r Eisenbahnfahrzeuge\n\nter sowie die Hinweise zum Erstellen kÃ¶nnen unter der Adresse [E-Mail-Adresse entfernt] angefordert werden.\n\nDer ZB oder das einbezogene EVU stellt sicher, dass EinsatzmerkblÃ¤tter vor dem Netzzugang erstellt, beim Ansprechpartner des regionalen Vertriebes vorgelegt und bei\n\nBedarf aktualisiert werden.\n\nDie EinsatzmerkblÃ¤tter sind fÃ¼r die Eisenbahnfahrzeuge zu\n\nerstellen, in denen sich Reisende oder Mitarbeiter zum\n\nZwecke der BefÃ¶rderung oder im Rahmen ihrer TÃ¤tigkeiten aufhalten kÃ¶nnen.\n\nDer ZB oder das einbezogene EVU stimmt die EinsatzmerkblÃ¤tter inhaltlich mit der Konzernstelle Notfallmanagement ab und stellt sie fÃ¼r eine Nutzung durch FremdrettungskrÃ¤fte zur VerfÃ¼gung.\n\nHinweis:\n\nDie Konzernstelle Notfallmanagement bietet dem ZB bzw.\n\ndem einbezogenen EVU an, die mit ihr abgestimmten EinsatzmerkblÃ¤tter im Internetauftritt des Notfallmanagements\n\nder DB AG zum Download bereitzustellen. HierfÃ¼r ist die\n\nvorherige vertragliche Anerkennung der Nutzungsbedingungen durch den ZB bzw. das einbezogenen EVU erforderlich.\n\n(3) Die Konzernstelle Notfallmanagement legt die erforderli- ZustÃ¤ndigkeit\n\nchen Inhalte fest, zu denen das Einsatzmerkblatt Informa- Konzernstelle\n\ntionen enthalten muss. Notfallmanagement\n\nï±\n\nGÃ¼ltig ab 09.12.2018",188,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174952/820b1600c2014069ba4816617d055714/Ril-423-1101-INB-2026-data.pdf\",\"normalized_sha256\":\"b9a4f2f733d0a347e43d4907cf8150abfba7a219ee8ffae53c7ca55d8379e4f9\",\"page\":3,\"source_id\":\"src_7982cd2d61d9b88505ea\",\"source_sha256\":\"8f686c9028cf9c6997fe357847bf62f5600781696595c2a4f187ab50c483a4c2\",\"source_version_id\":\"sv_f5f30bdad0d878ae4bfa9844\"}","4cd00b24599d09b23d97f5ab2199ceda2b541f52c37ab67b7ed7a0187915b6ae"],["chunk_82674e4112b3571e79535ebf","wiki/sources/ril-423-1110-inb-2026-data.md",0,"Seite 1","Richtlinie\n\nBahnbetrieb Notfallmanagement\n\nNotfallhilfe vorbereiten 423.1110\n\nSeite 1\n\n1 Allgemeines\n\n(1) Der ZB oder das einbezogene Eisenbahnverkehrsunter- Grundsatz\n\nnehmen, das im Bereich des Infrastrukturbetreibers DB\n\nNetz AG Fahrzeuge betreibt, ist verpflichtet, MaÃŸnahmen\n\nzur Vorbereitung und Organisation der Notfallhilfe gemÃ¤ÃŸ\n\ndieser Richtlinie durchzufÃ¼hren.\n\nDie detaillierten Bestimmungen dieser Richtlinie umfassen\n\noperative und planerische MaÃŸnahmen zur Vorbereitung,\n\nOrganisation und DurchfÃ¼hrung der Notfallhilfe im Bereich\n\ndes Infrastrukturbetreibers DB Netz AG.\n\n(2) Zur Notfallhilfe gehÃ¶ren die Elemente Bestandteile der\n\nNotfallhilfe\n\n- Zentrale Melde- und Alarmierungsstellen\n\n- MaÃŸnahmen zum Schutz der am Ereignisort tÃ¤tigen\n\nKrÃ¤fte\n\n- Fachberatung und Einsatz am Ereignisort\n\n- UnterstÃ¼tzung der Fremdrettung\n\n- Einsatz der Notfalltechnik\n\n- QualifizierungsmaÃŸnahmen und Ãœbungen.\n\n(3) Sofern regional zusÃ¤tzliche Vereinbarungen zum Notfall- ZusÃ¤tzliche Vermangement erforderlich sind, dÃ¼rfen regionale Vereinba- einbarungen\n\nrungen zwischen Infrastrukturbetreiber DB Netz AG und\n\ndem ZB oder dem einbezogenen EVU geschlossen werden.\n\n2 MaÃŸnahmen der Unternehmen, die Eisenbahnverkehr durchfÃ¼hren\n\n(1) Der ZB oder das einbezogene EVU ist verantwortlich fÃ¼r Grundsatz\n\ndie Vorbereitung, Planung und DurchfÃ¼hrung der MaÃŸnahmen der Notfallhilfe fÃ¼r den Bereich des Schienenverkehrs.\n\nDazu gehÃ¶ren\n\n- Personelle Ressourcen\n\n- Fachberatung vor Ort und Erreichbarkeiten\n\n- Materielle Ressourcen; AusrÃ¼stungen\n\n- Zusammenarbeit mit internen Stellen\n\n- Dokumentation; Notfallmappe\n\nFachautor: I.NBB 441; Markus Stern; Tel.: (9521) 104 GÃ¼ltig ab 12.12.2021",203,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174954/b36817facd4be81f7638174f12dcd548/Ril-423-1110-INB-2026-data.pdf\",\"normalized_sha256\":\"8850a407e78f128281c6d799d664df146ab1b78a1daab3c2122c053252f3f7f1\",\"page\":1,\"source_id\":\"src_f233954de96c0319eed1\",\"source_sha256\":\"2c4a10a1761ec885589737146d99e81e0d6928e6a87906a214123724cd8bf6a2\",\"source_version_id\":\"sv_6cd0e28e5d76dcc19ca06948\"}","deadd400102f0b3a18406b981e37bf64019c23fcd17e657edd56ad41861054fe"],["chunk_32cc923b978294b96392add4","wiki/sources/ril-423-1110-inb-2026-data.md",1,"Seite 2","Bahnbetrieb Notfallmanagement\n\nNotfallhilfe vorbereiten 423.1110\n\nSeite 2\n\nDokumentation; (2) Der ZB oder das einbezogene EVU entscheidet eigenver-\n\nNotfallmappe antwortlich, ob es MaÃŸnahmen nach Absatz 1 in einer Notfallmappe oder anderweitig dokumentiert.\n\nWird eine solche Notfallmappe erstellt, sind alle erforderlichen Unterlagen zur DurchfÃ¼hrung der Fachberatung in\n\ndieser Mappe aufzunehmen.\n\nÃ–rtliche Festle- (3) Der ZB oder das einbezogene EVU trifft weiter erforderligungen che MaÃŸnahmen zur Umsetzung der Notfallhilfe.\n\nDazu gehÃ¶ren u.a.\n\n- Festlegungen zur Unterrichtung des Infrastrukturbetreiber DB Netz AG Ã¼ber das bestehende Bereitschaftssystem sowie Ã¼ber vorhandene Rufnummernverzeichnisse des Notdienstes.\n\n- Benennung eines Ansprechpartners im Notfallmanagement.\n\nFestlegungen zur Umsetzung der Hilfeleistungen\n\ngemÃ¤ÃŸ Vorgabe der Nutzbedingungen Netz (NBN). *\n\nDer ZB oder das einbezogene EVU stellt sicher, dass\n\ndie vorgenannten Informationen, die die Schnittstellen zum Infrastrukturbetreiber DB Netz AG betreffen,\n\nbeim Ansprechpartner des regionalen Vertriebes\n\nvorgelegt und bei Bedarf eigenverantwortlich aktualisiert werden.\n\nPersonelle Res- (4) Der ZB oder das einbezogene EVU stellt sicher, dass gesourcen eignete Mitarbeiter zur DurchfÃ¼hrung der Aufgaben im\n\nNotdienst zur VerfÃ¼gung stehen.\n\nFachberatung (5) Bei Eintritt eines gefÃ¤hrlichen Ereignisses stellt der ZB\n\nvor Ort; Er- oder das einbezogene EVU sicher, dass Fachberater zur\n\nreichbarkeit UnterstÃ¼tzung des Notfallmanagers vor Ort zur VerfÃ¼gung\n\nstehen.\n\nDer Fachberater des jeweiligen ZB oder des einbezogenen EVU soll in der Regel 120 Minuten nach der Alarmierung den Notfallmanager vor Ort bei ZB oder EVUspezifischen Belangen unterstÃ¼tzen.",221,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174954/b36817facd4be81f7638174f12dcd548/Ril-423-1110-INB-2026-data.pdf\",\"normalized_sha256\":\"8850a407e78f128281c6d799d664df146ab1b78a1daab3c2122c053252f3f7f1\",\"page\":2,\"source_id\":\"src_f233954de96c0319eed1\",\"so