INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_6b78ad451b1f8682d1e8bc88","wiki/sources/ril-436-inb-2026-data.md",51,"Seite 43","Zuglaufmeldungen, Zugmeldungen 436.0002\n\nSeite 3\n\n(5) Die Ankunftsmeldung wird durch den ZugfÃ¼hrer bzw. durch den Ã¶rtlichen\n\nBahnhofsfahrdienstleiter an den Zugleiter gegeben. Die Ankunftsmeldung lautet:\n\nâ€žZug (Nummer) in (Name der Zuglaufstelle / Zugmeldestelle).â€œ Ankunftsmeldung\n\nSie darf erst gegeben werden, wenn der Zug vollstÃ¤ndig an der festgelegten\n\nZugschlussstelle fÃ¼r die Einfahrt (Betriebsstellenbuch / Streckenbuch) vorbeigefahren ist bzw. die letzte Weiche des Einfahrweges gerÃ¤umt hat. Bahnhofsfahrdienstleiter von BahnhÃ¶fen mit Einfahrsignal dÃ¼rfen die Ankunftsmeldung\n\nerst dann geben, wenn sie eine RÃ¤umungsprÃ¼fung durchgefÃ¼hrt haben.\n\n(6) Die Verlassensmeldung an den Zugleiter wird nur auf unbesetzten Zuglauf- Verlassensstellen gegeben. Sie kann von einem anderen Mitarbeiter im Bahnbetrieb oder meldung\n\nvom ZugfÃ¼hrer eines anderen Zuges gegeben werden. Die Verlassensmeldung lautet:\n\nâ€žZug (Nummer) hat (Name der Zuglaufstelle) verlassen.â€œ\n\nSie darf erst gegeben werden, wenn der Zug vollstÃ¤ndig an der festgelegten\n\nZugschlussstelle fÃ¼r die Ausfahrt (Betriebsstellenbuch / Streckenbuch), bzw.\n\nan der Trapeztafel der Gegenrichtung vorbeigefahren ist.\n\n(7) Die Fahrwegsicherungsmeldung an den Zugleiter wird vom ZugfÃ¼hrer des Fahrwegsicheersten Zuges auf unbesetzten Zuglaufstellen ohne RÃ¼ckfallweichen und Rich- rungsmeldung\n\ntungsbetrieb gegeben. Die Fahrwegsicherungsmeldung lautet:\n\nâ€žFahrweg fÃ¼r Zug (Nummer) nach Gleis (Nummer) gesichert.â€œ\n\nDie Fahrwegsicherungsmeldung ist vorgesehen, wenn der zweite Zug ohne\n\nHalt an der Trapeztafel einfahren soll.\n\nSie darf erst gegeben werden, wenn die Voraussetzungen fÃ¼r die Einfahrt des\n\nZuges nach Modul 436.0004 Abschnitt 3 (2) b) erfÃ¼llt sind.",216,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174764/9e7f4084ba2db8f336b9852caf1a8f55/Ril-436-INB-2026-data.pdf\",\"normalized_sha256\":\"b8973395658fa33ddb00227bf13dbf07e6bf1aa9f64f6cea927b27d037b92427\",\"page\":43,\"source_id\":\"src_28f7316308c44534e6be\",\"source_sha256\":\"34b4df17aa8dd8774476cd398b937be0bf235c59cd5c7c6ed8a955278e059560\",\"source_version_id\":\"sv_211aedcfc7be5351fe829e9a\"}","51b6f74482883cfe58c3f6a1f811ef2198674586a1442b2e4ae50b5aa0a56e49"],["chunk_18761892a112e84ca22897e9","wiki/sources/ril-436-inb-2026-data.md",52,"Seite 43","(8) Die Abstellmeldung an den Zugleiter wird vom ZugfÃ¼hrer auf unbesetzten Abstellmel-\n\nZuglaufstellen gegeben. Die Abstellmeldung lautet: dung\n\nâ€žZug (Nummer) / Rangierfahrt in (Name der Zuglaufstelle) in Gleis (Nummer) abgestellt.â€œ\n\nSie darf nur gegeben werden, wenn die Rangierfahrt im Nebengleis abgestellt\n\nist, in den Hauptgleisen keine Fahrzeuge zurÃ¼ckgelassen wurden und der\n\nZugfÃ¼hrerschlÃ¼ssel sich in Verwahrung des Meldenden befindet.\n\nDer Abstellmeldung muss immer eine Ankunftsmeldung oder eine Rangiererlaubnis vorausgegangen sein.\n\n(9) FÃ¼r ZÃ¼ge mit Schiebetriebfahrzeugen, die nicht mit dem Zug gekuppelt sind, Schiebetriebwerden die Zuglaufmeldungen â€“ mit Ausnahme der Fahrwegsicherungsmel- fahrzeug\n\ndung â€“ ergÃ¤nzt durch den Zusatz:\n\nâ€žMit Schiebetriebfahrzeug, das nicht mit dem Zug gekuppelt ist.\n\n(10) Kehrt ein Schiebetriebfahrzeug von der freien Strecke zurÃ¼ck, lautet die An- ZurÃ¼ckkehkunftsmeldung auf der ersten bei der RÃ¼ckfahrt erreichten Zuglaufstelle: rendes Schiebetriebfahr-\n\nâ€žSchiebetriebfahrzeug von Zug (Nummer) in (Name der Zuglaufstelle /\n\nzeug\n\nZugmeldestelle).â€œ\n\nGÃ¼ltig ab: 13.12.2015",142,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174764/9e7f4084ba2db8f336b9852caf1a8f55/Ril-436-INB-2026-data.pdf\",\"normalized_sha256\":\"b8973395658fa33ddb00227bf13dbf07e6bf1aa9f64f6cea927b27d037b92427\",\"page\":43,\"source_id\":\"src_28f7316308c44534e6be\",\"source_sha256\":\"34b4df17aa8dd8774476cd398b937be0bf235c59cd5c7c6ed8a955278e059560\",\"source_version_id\":\"sv_211aedcfc7be5351fe829e9a\"}","70df21d8677f34037c8bc21edacd4fc0c936a063dc66cacc54d64d46b74fdc3c"],["chunk_2171c0aeceb5b2eaa988e199","wiki/sources/ril-436-inb-2026-data.md",53,"Seite 44","Zuglaufmeldungen, Zugmeldungen 436.0002\n\nSeite 4\n\n2 Zugmeldungen\n\nZugmeldun- (1) Der Zugleiter regelt die Zugfolge und die Reihenfolge der ZÃ¼ge, die in die\n\ngen Zugleitstrecke hineinfahren oder sie verlassen, mit dem benachbarten Zugleiter bzw. Fahrdienstleiter durch Zugmeldungen. Zugmeldungen sind nicht erforderlich, wenn der Zugleiter zugleich Fahrdienstleiter der benachbarten\n\nZugmeldestelle ist.\n\nIn die Zugleit- (2) FÃ¼r einen in die Zugleitstrecke einfahrenden Zug ist folgendes zu beachten:\n\nstrecke eina) Abweichend von Richtlinie 408 wird der Zug mit dem Wortlaut angenomfahrender Zug\n\nmen:\n\nâ€žZug (Nummer) bis (Name der Zuglaufstelle) ja.â€œ\n\nDamit gilt die Fahrerlaubnis des Zugleiters als erteilt.\n\nb) Der benachbarte Zugleiter bzw. Fahrdienstleiter Ã¼bermittelt vor der Zustimmung zur Abfahrt dem ZugfÃ¼hrer die Fahrerlaubnis und vermerkt dies\n\nim Zugmeldebuch.\n\nBei besonderen Ã¶rtlichen VerhÃ¤ltnissen kann im Betriebsstellenbuch / Streckenbuch eine andere Ãœbermittlung der Fahrerlaubnis angeordnet sein.\n\nc) Der Zugleiter meldet den Zug zurÃ¼ck, nachdem er fÃ¼r diesen eine Ankunftsmeldung erhalten hat oder â€“ sofern er selbst Fahrdienstleiter bzw.\n\nÃ¶rtlicher Bahnhofsfahrdienstleiter ist â€“ bei dem Zug eine RÃ¤umungsprÃ¼fung\n\ndurchgefÃ¼hrt wurde.\n\nDie Zugleit- (3) FÃ¼r einen die Zugleitstrecke verlassenden Zug ist folgendes zu beachten:\n\nstrecke vera) Der Zugleiter darf dem Zug die Fahrerlaubnis Ã¼ber die letzte Zuglaufstelle\n\nlassender Zug\n\nhinaus erst erteilen, wenn der Zug von der benachbarten Zugmeldestelle\n\nangenommen ist.\n\nb) Der benachbarte Zugleiter bzw. Fahrdienstleiter gibt fÃ¼r jeden Zug eine\n\nRÃ¼ckmeldung.\n\nBenachbarte (4) FÃ¼r das Zusammenwirken zweier Zugleiter, deren Zugleitstrecken aneinander",226,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174764/9e7f4084ba2db8f336b9852caf1a8f55/Ril-436-INB-2026-data.pdf\",\"normalized_sha256\":\"b8973395658fa33ddb00227bf13dbf07e6bf1aa9f64f6cea927b27d037b92427\",\"page\":44,\"source_id\":\"src_28f7316308c44534e6be\",\"source_sha256\":\"34b4df17aa8dd8774476cd398b937be0bf235c59cd5c7c6ed8a955278e059560\",\"source_version_id\":\"sv_211aedcfc7be5351fe829e9a\"}","6c99e4b15c5941293a389f2ae16f06af5b5f4866d5ef98fd5166a7b0b26888bf"],["chunk_ca87b84532a6a064a0994e40","wiki/sources/ril-436-inb-2026-data.md",54,"Seite 44","Zugleiter anstoÃŸen, kÃ¶nnen im Betriebsstellenbuch weitere Regelungen getroffen sein.\n\n3 Benachrichtigen von SchrankenwÃ¤rtern, BahnÃ¼bergangsposten und Arbeitsstellen\n\nSchranken- (1) MÃ¼ssen SchrankenwÃ¤rter Ã¼ber Zugfahrten benachrichtigt werden, ist dies im\n\nwÃ¤rter Betriebsstellenbuch geregelt.\n\nBahnÃ¼ber- (2) FÃ¼r die Benachrichtigung von SchrankenwÃ¤rtern, BahnÃ¼bergangsposten und\n\ngangsposten Arbeitsstellen Ã¼ber Zugfahrten ist zu berÃ¼cksichtigen:\n\nund Arbeits-\n\n- Der Zugleiter hat die Benachrichtigung vorzunehmen. FÃ¤hrt der Zug auf eistellen auf der\n\nfreien Strecke ner benachbarten Zugmeldestelle ab und befinden sich BahnÃ¼bergÃ¤nge /\n\nArbeitsstellen zwischen Zugmeldestelle und erster Zuglaufstelle, obliegt\n\ndem Fahrdienstleiter die Benachrichtigung.\n\n- Auf der letzten Zuglaufstelle vor dem Standort der BahnÃ¼bergangsposten /\n\nArbeitsstellen ist Fahrerlaubnis anzuordnen.\n\n- Die Benachrichtigung muss erfolgen, bevor dem Zug die Fahrerlaubnis\n\nÃ¼ber die vor dem BahnÃ¼bergang bzw. der Arbeitsstelle liegende Zuglaufstelle hinaus erteilt wird.\n\nGÃ¼ltig ab: 13.12.2015",125,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174764/9e7f4084ba2db8f336b9852caf1a8f55/Ril-436-INB-2026-data.pdf\",\"normalized_sha256\":\"b8973395658fa33ddb00227bf13dbf07e6bf1aa9f64f6cea927b27d037b92427\",\"page\":44,\"source_id\":\"src_28f7316308c44534e6be\",\"source_sha256\":\"34b4df17aa8dd8774476cd398b937be0bf235c59cd5c7c6ed8a955278e059560\",\"source_version_id\":\"sv_211aedcfc7be5351fe829e9a\"}","d126edea1a0215e311279b0aaad30377bb9c488f79fa45e14057cd209bf3d9a3"],["chunk_d84c63d84a5a6eb524e77095","wiki/sources/ril-436-inb-2026-data.md",55,"Seite 45","Zuglaufmeldungen, Zugmeldungen 436.0002\n\nSeite 5\n\n- Die Benachrichtigung darf frÃ¼hestens bis zu fÃ¼nf Minuten vor dem Erteilen\n\nder Fahrerlaubnis erfolgen.\n\n- Ein SchrankenwÃ¤rter bzw. BahnÃ¼bergangsposten ist mit den Worten:\n\nâ€žZug (Nummer) in (Name der Zuglaufstelle / Zugmeldestelle) voraussichtlich ab (Minute der voraussichtlichen Abfahrtzeit)â€œ,\n\nzu benachrichtigen.\n\n- Eine Arbeitsstelle ist mit den Worten:\n\nâ€žZug (Nummer) von (Name der letzten Zuglaufstelle / Zugmeldestelle\n\nvor der Arbeitsstelle) nach (Name der ersten Zuglaufstelle / Zugmeldestelle hinter der Arbeitsstelle)â€œ,\n\nzu benachrichtigen.\n\n(3) Der Zugleiter darf dem Beginn der Arbeiten erst zustimmen, wenn das Gleis, Beginn und\n\nin dem gearbeitet werden soll, im Zugmeldebuch als frei gekennzeichnet ist. Ende der Ar-\n\nBei Arbeiten zwischen der benachbarten Zugmeldestelle und der ersten Zug- beiten\n\nlaufstelle verstÃ¤ndigen sich Fahrdienstleiter und Zugleiter darÃ¼ber, dass Arbeitsstellen zu benachrichtigen sind bzw. dass die Benachrichtigung nicht\n\nmehr erforderlich ist.\n\nï±\n\nGÃ¼ltig ab: 13.12.2015",140,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174764/9e7f4084ba2db8f336b9852caf1a8f55/Ril-436-INB-2026-data.pdf\",\"normalized_sha256\":\"b8973395658fa33ddb00227bf13dbf07e6bf1aa9f64f6cea927b27d037b92427\",\"page\":45